#include <iostream>
#include <vector>
#include <algorithm>
#include <set>

using namespace std;

#define int long long

int st[1000005];
int a[1000005];
int b[1000005];
int c[1000005];
int fans=1e18;

void check()
{
    for (int i=0; i<18; i++)
    {
        a[i]=c[i];
    }
    for (int i=0; i<17; i++)
    {
        if (b[i]>0)
        {
            a[i+1]++;
            a[i]-=10;
            a[0]--;
        }
    }
    if (a[0]<-6)
    {
        a[0]+=11;
        a[1]--;
    }
    if (a[0]>6)
    {
        a[0]-=11;
        a[1]++;
    }
    int total=0;
    for (int i=0; i<18; i++)
    {
        total+=abs(a[i])*(i+1);
    }
    fans=min(fans,total);
}

void generate_combinations(int step)
{
    if (step>=17)
    {
        check();
        return;
    }
    for (int val=0; val<2; val++)
    {
        b[step]=val;
        generate_combinations(step+1);
    }
}

int main()
{
    int n;
    cin>>n;
    st[0]=1;
    for (int i=1; i<18; i++)
    {
        st[i]=st[i-1]*10+1;
    }
    int current=n;
    int position=17;
    while (current>0)
    {
        c[position]=current/st[position];
        current%=st[position];
        position--;
    }
    generate_combinations(0);
    cout<<fans;
}
